(7073890, 1075785, 100831, '<td valign="top">look deep into my soul.... best reflection image I''ve seen in a long time. Bump</td>', 'look deep into my soul.... best reflection image I''ve seen in a long time. Bump', '2013-07-19 09:19:56.000000', NULL, 1),
(7073923, 1075938, 68504, '<td valign="top">this makes me so uncomfortable ... seven, for now.</td>', 'this makes me so uncomfortable ... seven, for now.', '2013-07-19 11:41:41.000000', NULL, 1),
(7073925, 1075879, 68504, '<td valign="top">what have we done to ourselves?</td>', 'what have we done to ourselves?', '2013-07-19 11:44:26.000000', NULL, 1),
(7073928, 1075273, 61396, '<td valign="top">A self defying piece, that may demonstrate that visual art may be boring to the blind. This specific piece however is not boring even to blind people, if instead of taking a picture of it, you cut it off the wall, frame it, and make sure no glass separates it from inquisitive hands. Then even blind people can enjoy the raggedness of the surface, the different shapes and materials composing it, and imagine what the artist may have meant, what she saw and what she missed, not bothering at all whether she meant to fool them.  As they know well that once the piece is done, it is theirs to interpret and enjoy as much as it is the artist''s. It is a pity they will not be able to appreciate the red spots.</td>', 'A self defying piece, that may demonstrate that visual art may be boring to the blind. This specific piece however is not boring even to blind people, if instead of taking a picture of it, you cut it off the wall, frame it, and make sure no glass separates it from inquisitive hands. Then even blind people can enjoy the raggedness of the surface, the different shapes and materials composing it, and imagine what the artist may have meant, what she saw and what she missed, not bothering at all whether she meant to fool them.  As they know well that once the piece is done, it is theirs to interpret and enjoy as much as it is the artist''s. It is a pity they will not be able to appreciate the red spots.', '2013-07-19 11:48:59.000000', NULL, 1),
(7073932, 1075866, 61396, '<td valign="top">It is so fragile, the bench, and on the verge of falling backward, that I feel compelled to try it right away before it falls into the ditch. The light is to die for (that''s a good thing).</td>', 'It is so fragile, the bench, and on the verge of falling backward, that I feel compelled to try it right away before it falls into the ditch. The light is to die for (that''s a good thing).', '2013-07-19 11:51:38.000000', NULL, 1),
(7073950, 1075933, 63218, '<td valign="top">I can see this hanging in the lobby of a grand old hotel (formerly a mansion belonging to a titan of industry from the 19th century) that caters to the elite of bird-watchers &amp; botanists. <br/> <br/>Looking at this emotionally is satisfying, for it transcends its own documentary qualities. The rich velvet shadows, the gentle yet intense light, the wonderful range of color. The clear detail. I''m pleased you did not fade the BG totally to black. And I like the square crop. Looking at it with the eyes of one who often shoots flowers, I can''t figure out how you got the lily pad &amp; the flower at right angles. Or so it seems. So, it''s a visual pleasure &amp; a brain-teaser at the same time. Excellent!</td>', 'I can see this hanging in the lobby of a grand old hotel (formerly a mansion belonging to a titan of industry from the 19th century) that caters to the elite of bird-watchers & botanists.  Looking at this emotionally is satisfying, for it transcends its own documentary qualities. The rich velvet shadows, the gentle yet intense light, the wonderful range of color. The clear detail. I''m pleased you did not fade the BG totally to black. And I like the square crop. Looking at it with the eyes of one who often shoots flowers, I can''t figure out how you got the lily pad & the flower at right angles. Or so it seems. So, it''s a visual pleasure & a brain-teaser at the same time. Excellent!', '2013-07-19 12:13:03.000000', NULL, 1),
(7073956, 1075960, 63218, '<td valign="top">I do believe I laughed out loud when I saw this. I''ve never seen anything quite like it. It''s surreal &amp; literal, serious &amp; comic. The light is so even I can see colors thru the wings--the light is the most magical thing about it. Technically well done, artistically spot-on, easy to look at &amp; spiritually rewarding. Excellent!</td>', 'I do believe I laughed out loud when I saw this. I''ve never seen anything quite like it. It''s surreal & literal, serious & comic. The light is so even I can see colors thru the wings--the light is the most magical thing about it. Technically well done, artistically spot-on, easy to look at & spiritually rewarding. Excellent!', '2013-07-19 12:20:56.000000', NULL, 1),
(7073988, 1075923, 113591, '<td valign="top">My only 10.<br/> <br/>The lines that are straight but skewed, create a lot of tension.<br/> <br/>One can imagine numerous stories to flow out of this image.<br/> <br/>The hair, the look, the leg, everything to do with the girl is so interesting.<br/> <br/>You managed to make the background important and available, but not overbearing or distracting.</td>', 'My only 10. The lines that are straight but skewed, create a lot of tension. One can imagine numerous stories to flow out of this image. The hair, the look, the leg, everything to do with the girl is so interesting. You managed to make the background important and available, but not overbearing or distracting.', '2013-07-19 13:38:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7074024, 1075879, 12611, '<td valign="top">This has whimsy and absurdity, yet the dead serious feel of a Russian World War Two propaganda campaign. Each time I look at this I feel differently about it, but I am drawn to the imbalance, the sharpness and blur. Perhaps I am drawn most to the mystery mixed with sentimentality.</td>', 'This has whimsy and absurdity, yet the dead serious feel of a Russian World War Two propaganda campaign. Each time I look at this I feel differently about it, but I am drawn to the imbalance, the sharpness and blur. Perhaps I am drawn most to the mystery mixed with sentimentality.', '2013-07-19 15:51:35.000000', NULL, 1),
(7074052, 1075842, 11769, '<td valign="top">love the flow</td>', 'love the flow', '2013-07-19 16:27:12.000000', NULL, 1),
(7074053, 1075450, 11769, '<td valign="top">I love the feeling of "story" in this.</td>', 'I love the feeling of "story" in this.', '2013-07-19 16:28:27.000000', NULL, 1),
(7074057, 1075859, 11769, '<td valign="top">I have a feeling the "nothing" will be not very much. I''ve been doing this most of my life.</td>', 'I have a feeling the "nothing" will be not very much. I''ve been doing this most of my life.', '2013-07-19 16:30:36.000000', NULL, 1),
(7074060, 1075898, 11769, '<td valign="top">my foe is my friend. very emotional piece.</td>', 'my foe is my friend. very emotional piece.', '2013-07-19 16:32:28.000000', NULL, 1),
(7074061, 1075863, 11769, '<td valign="top">beautiful abstract</td>', 'beautiful abstract', '2013-07-19 16:34:25.000000', NULL, 1),
(7074062, 1075958, 113591, '<td valign="top">Lovely use of mono?colour.<br/> <br/>The woman moving out of the image makes such a balanced counterpoint.<br/> <br/>My eyes continued to move from left to right, not being able to decide where to rest or linger, the image becoming restless thereby, and that makes me want to know more. <br/> <br/>Both have room to grow, but are full-grown already. <br/> <br/>Maybe the spell has been broken, and she has just decided not to be an hydrangea anymore, and is moving back into the world.</td>', 'Lovely use of mono?colour. The woman moving out of the image makes such a balanced counterpoint. My eyes continued to move from left to right, not being able to decide where to rest or linger, the image becoming restless thereby, and that makes me want to know more.  Both have room to grow, but are full-grown already.  Maybe the spell has been broken, and she has just decided not to be an hydrangea anymore, and is moving back into the world.', '2013-07-19 16:36:02.000000', NULL, 1),
(7074064, 1075859, 68504, '<td valign="top">what''s not to like? a photograph by Samuel Beckett.</td>', 'what''s not to like? a photograph by Samuel Beckett.', '2013-07-19 16:36:43.000000', NULL, 1),
(7074074, 1075861, 68504, '<td valign="top">maybe it won''t. not a bad thing at all.</td>', 'maybe it won''t. not a bad thing at all.', '2013-07-19 16:40:45.000000', NULL, 1),
(7074077, 1075945, 11769, '<td valign="top">beautiful work. Where reality is just enough to draw me in and the abstraction of emotion keeps me longing for more.</td>', 'beautiful work. Where reality is just enough to draw me in and the abstraction of emotion keeps me longing for more.', '2013-07-19 16:41:12.000000', NULL, 1),
(7074078, 1075949, 11769, '<td valign="top">a lovely blue</td>', 'a lovely blue', '2013-07-19 16:41:36.000000', NULL, 1),
(7074080, 1075433, 11769, '<td valign="top">Beautiful colors and blur</td>', 'Beautiful colors and blur', '2013-07-19 16:42:57.000000', NULL, 1),
(7074081, 1075958, 68504, '<td valign="top">what to say? maybe just "hydrangeas." compelling in its silence.</td>', 'what to say? maybe just "hydrangeas." compelling in its silence.', '2013-07-19 16:43:01.000000', NULL, 1),
(7074084, 1075906, 11769, '<td valign="top">love the title. this is absolutely gorgeous.</td>', 'love the title. this is absolutely gorgeous.', '2013-07-19 16:44:54.000000', NULL, 1),
(7074096, 1075957, 12611, '<td valign="top">Shimmering beautiful texture, in the way that black is when it turns to blue, with a crystal feel of ice cold winter nights.</td>', 'Shimmering beautiful texture, in the way that black is when it turns to blue, with a crystal feel of ice cold winter nights.', '2013-07-19 16:56:29.000000', NULL, 1),
(7074099, 1075863, 12611, '<td valign="top">Perfect southwest color palette pastels, in the light, waving in the breeze.</td>', 'Perfect southwest color palette pastels, in the light, waving in the breeze.', '2013-07-19 16:57:43.000000', NULL, 1),
(7074102, 1075520, 12611, '<td valign="top">The imperfection, the low key- all makes the scene beautiful, in a melancholy remembrance sort of way.</td>', 'The imperfection, the low key- all makes the scene beautiful, in a melancholy remembrance sort of way.', '2013-07-19 16:59:09.000000', NULL, 1),
(7074104, 1075887, 12611, '<td valign="top">perfect silhouetted shapes 4 individuals bound together be their actions, the activity, all in the high key sun.</td>', 'perfect silhouetted shapes 4 individuals bound together be their actions, the activity, all in the high key sun.', '2013-07-19 17:01:46.000000', NULL, 1),
(7074108, 1075785, 12611, '<td valign="top">As we settle in to modernity, human interactions with nature and man made constructs affect our appearance, and create a wildly distorted and multi-colored (almost clown-like) personas.<br/> <br/>The face literally reflects, and dominates the image ,  the viewer resigns, steps back, and shyly begins intellectual reflection, and the snake thereby swallows it''s tail.</td>', 'As we settle in to modernity, human interactions with nature and man made constructs affect our appearance, and create a wildly distorted and multi-colored (almost clown-like) personas. The face literally reflects, and dominates the image ,  the viewer resigns, steps back, and shyly begins intellectual reflection, and the snake thereby swallows it''s tail.', '2013-07-19 17:15:44.000000', NULL, 1),
(7074109, 1075534, 12611, '<td valign="top">The high key, symmetry, futuristic chair, all work perfectly. I am particularly fond of how the fluorescent lights turn into a hand drawn mess as the ceiling fades away. The shadow lines and red locks form a nice "blueprint" detail feel.<br/> <br/>All in all a very solid shot. (any digital noise and distortion adds to the context.)</td>', 'The high key, symmetry, futuristic chair, all work perfectly. I am particularly fond of how the fluorescent lights turn into a hand drawn mess as the ceiling fades away. The shadow lines and red locks form a nice "blueprint" detail feel. All in all a very solid shot. (any digital noise and distortion adds to the context.)', '2013-07-19 17:15:46.000000', NULL, 1),
(7074112, 1075836, 68504, '<td valign="top">the windowness, a cat in the window, we cannot plumb the depths, but there are windows, a cat, windows in windows. stuck in a wall. stuck in a wall a satellite receiver.</td>', 'the windowness, a cat in the window, we cannot plumb the depths, but there are windows, a cat, windows in windows. stuck in a wall. stuck in a wall a satellite receiver.', '2013-07-19 17:21:46.000000', NULL, 1),
(7074114, 1075842, 12611, '<td valign="top">Lusciously wonderful colors. Strands of blue into gold of pure light- the extra long aspect ratio prolonging the visual experience. Terrific range of tones, turning this shot into a veritable lotus flower, pulling the viewer in and not letting go.</td>', 'Lusciously wonderful colors. Strands of blue into gold of pure light- the extra long aspect ratio prolonging the visual experience. Terrific range of tones, turning this shot into a veritable lotus flower, pulling the viewer in and not letting go.', '2013-07-19 17:24:00.000000', NULL, 1),
(7074119, 1075711, 12611, '<td valign="top">An upside down insect- transformed into the body of huge headed shadow god- all viewed in the context of the human eye, open receptive to light, seed-like.<br/> <br/>I can''t help but add my Rorschach test answers to the mystery shapes presented in silhouette. If not, I succumb to an even more nightmarish and Kafkaesque evil lurking just beyond the senses.</td>', 'An upside down insect- transformed into the body of huge headed shadow god- all viewed in the context of the human eye, open receptive to light, seed-like. I can''t help but add my Rorschach test answers to the mystery shapes presented in silhouette. If not, I succumb to an even more nightmarish and Kafkaesque evil lurking just beyond the senses.', '2013-07-19 17:26:28.000000', NULL, 1),
(7074136, 1075450, 57447, '<td valign="top">So reminds me of a Bresson!  Nice work.</td>', 'So reminds me of a Bresson!  Nice work.', '2013-07-19 17:56:36.000000', NULL, 1),
(7074140, 1075916, 68504, '<td valign="top">yes, that is the truth: in the end all battles are blurs, and celebration and blame are irrelevant. indeed the lines are blurred.</td>', 'yes, that is the truth: in the end all battles are blurs, and celebration and blame are irrelevant. indeed the lines are blurred.', '2013-07-19 18:09:41.000000', NULL, 1),
(7074370, 1075273, 100831, '<td valign="top">Winogrand, Eggleston take note! You are not so boring. Make something out of nothing should be everybody''s middle name. ART ART ART... I love it.</td>', 'Winogrand, Eggleston take note! You are not so boring. Make something out of nothing should be everybody''s middle name. ART ART ART... I love it.', '2013-07-19 23:25:20.000000', NULL, 1),
(7074415, 1075608, 100831, '<td valign="top">gorgeous! love the energy.</td>', 'gorgeous! love the energy.', '2013-07-20 00:13:26.000000', NULL, 1),
(7074416, 1075952, 100831, '<td valign="top">intense... love it.</td>', 'intense... love it.', '2013-07-20 00:14:19.000000', NULL, 1),
(7074417, 1075953, 76335, '<td valign="top">A struggle seems to be taking place here, though the more I try to follow it and make sense of it, the more evasive it becomes. Wonderful sci-fi, very psychedelic.</td>', 'A struggle seems to be taking place here, though the more I try to follow it and make sense of it, the more evasive it becomes. Wonderful sci-fi, very psychedelic.', '2013-07-20 00:16:58.000000', NULL, 1),
(7074418, 1075953, 50641, '<td valign="top">-Disjointed limbs, squamous cells, red and blue states, hand over face as if with a pillow case. Stifling remorse. An anti-superhero forcing you to say uncle.</td>', '-Disjointed limbs, squamous cells, red and blue states, hand over face as if with a pillow case. Stifling remorse. An anti-superhero forcing you to say uncle.', '2013-07-20 00:18:13.000000', NULL, 1),
(7074420, 1075506, 76335, '<td valign="top">To dismiss this as a snapshot would be a great loss. And maybe it is a snapshot. (I hope it is.) Meaningless definitions aside, what we have here is a beautifully captured farewell. The longer-than-handheld exposure has captured not only the woman''s smeary wave, but a ghostly hand (the photographer''s?) waving back. The license plate adds local color. The mirror and A-pillar not only enhance the composition but also add point of view. I would love to see this as the first in a series, maybe a photographic travelogue from behind the driver''s seat.</td>', 'To dismiss this as a snapshot would be a great loss. And maybe it is a snapshot. (I hope it is.) Meaningless definitions aside, what we have here is a beautifully captured farewell. The longer-than-handheld exposure has captured not only the woman''s smeary wave, but a ghostly hand (the photographer''s?) waving back. The license plate adds local color. The mirror and A-pillar not only enhance the composition but also add point of view. I would love to see this as the first in a series, maybe a photographic travelogue from behind the driver''s seat.', '2013-07-20 00:19:34.000000', NULL, 1),
(7074431, 1075953, 100831, '<td valign="top">wonderful graphic... love the colors.</td>', 'wonderful graphic... love the colors.', '2013-07-20 00:56:29.000000', NULL, 1),
(7074441, 1075433, 63218, '<td valign="top">I like the way my mind goes completely blank when I look at this. I see the best elements of dreams, hallucinations, mirages, &amp; forgotten promises. And some very nice color.</td>', 'I like the way my mind goes completely blank when I look at this. I see the best elements of dreams, hallucinations, mirages, & forgotten promises. And some very nice color.', '2013-07-20 02:09:15.000000', NULL, 1),
(7074452, 1075913, 98533, '<td valign="top">sounds great.</td>', 'sounds great.', '2013-07-20 04:45:45.000000', NULL, 1),
(7074453, 1075693, 98533, '<td valign="top">like color and hole feeling</td>', 'like color and hole feeling', '2013-07-20 04:46:44.000000', NULL, 1),
(7074454, 1075861, 98533, '<td valign="top">great point of view.</td>', 'great point of view.', '2013-07-20 04:47:18.000000', NULL, 1),
(7074455, 1075959, 98533, '<td valign="top">Awesome</td>', 'Awesome', '2013-07-20 04:49:57.000000', NULL, 1),
(7074490, 1075852, 63218, '<td valign="top">Nice title. I don''t see fire in this so the troll must be burning with passionate love for something. Probably dinner. I''m pretty sure trolls are hungry all the time. The colors are what caught my eye first, the combination of gold and green, the bright highlight/deep shadow. The implied fine texture is interesting to look at &amp; relaxing at the same time. It has line, shape, &amp; shadow but no real subject, making it an excellent abstract. A definite keeper.</td>', 'Nice title. I don''t see fire in this so the troll must be burning with passionate love for something. Probably dinner. I''m pretty sure trolls are hungry all the time. The colors are what caught my eye first, the combination of gold and green, the bright highlight/deep shadow. The implied fine texture is interesting to look at & relaxing at the same time. It has line, shape, & shadow but no real subject, making it an excellent abstract. A definite keeper.', '2013-07-20 10:35:38.000000', NULL, 1),
(7074492, 1075508, 63218, '<td valign="top">I have tried many times to get this shot because I like the way the tightly furled leaf contrasts against the open leaves. I would be very happy with this shot if it was mine, so it''s an instant fav for me. The green is strong without being overpowering, &amp; the highlighted areas keep my eye moving. Nice DOF. The BG leaf in shadow makes a strong counterpoint to the candle leaf. Like a good song, to listen to over &amp; over, I linger to move my eye around this. Good job.</td>', 'I have tried many times to get this shot because I like the way the tightly furled leaf contrasts against the open leaves. I would be very happy with this shot if it was mine, so it''s an instant fav for me. The green is strong without being overpowering, & the highlighted areas keep my eye moving. Nice DOF. The BG leaf in shadow makes a strong counterpoint to the candle leaf. Like a good song, to listen to over & over, I linger to move my eye around this. Good job.', '2013-07-20 10:42:59.000000', NULL, 1),
(7074505, 1075898, 63218, '<td valign="top">There''s nothing there, yet my eye enjoys roving around this image looking for something. Motion blur might''ve been used to create this, but it''s not what I''m thinking about when I look at it. I''m just enjoying the line, shape, &amp; tone of this interesting abstract. Good work.</td>', 'There''s nothing there, yet my eye enjoys roving around this image looking for something. Motion blur might''ve been used to create this, but it''s not what I''m thinking about when I look at it. I''m just enjoying the line, shape, & tone of this interesting abstract. Good work.', '2013-07-20 12:02:04.000000', NULL, 1),
(7074507, 1075165, 63218, '<td valign="top">Gosh, why so small?  It''s a nice shot of a beautiful bird.</td>', 'Gosh, why so small?  It''s a nice shot of a beautiful bird.', '2013-07-20 12:13:04.000000', NULL, 1),
(7074509, 1075218, 63218, '<td valign="top">Expressive hands, you could take some more shots of them.</td>', 'Expressive hands, you could take some more shots of them.', '2013-07-20 12:17:36.000000', NULL, 1),
(7074516, 1075900, 63218, '<td valign="top">I''m glad you didn''t impose a vignette on this. It''s quite charming &amp; the wall detail is wonderful.</td>', 'I''m glad you didn''t impose a vignette on this. It''s quite charming & the wall detail is wonderful.', '2013-07-20 13:10:59.000000', NULL, 1),
(7074520, 1075271, 63218, '<td valign="top">That window looks absolutely tiny.</td>', 'That window looks absolutely tiny.', '2013-07-20 13:35:14.000000', NULL, 1),
(7074524, 1075901, 63218, '<td valign="top">Took me a moment or two to see the bird &amp; that was when I started thinking maybe this was a sculpture that I''d like to see.</td>', 'Took me a moment or two to see the bird & that was when I started thinking maybe this was a sculpture that I''d like to see.', '2013-07-20 13:37:59.000000', NULL, 1),
(7074527, 1075693, 63218, '<td valign="top">Just for a moment this did look like a painting.</td>', 'Just for a moment this did look like a painting.', '2013-07-20 13:42:45.000000', NULL, 1),
(7074589, 1075635, 50641, '<td valign="top">Murky, dingy, dim - debilitated Caribbean colors. Some sort of flora from the Devil''s Triangle. Who is it pointing at? Who is it damning? Oh. I don''t want to know. <br/> <br/>Made my top 3.</td>', 'Murky, dingy, dim - debilitated Caribbean colors. Some sort of flora from the Devil''s Triangle. Who is it pointing at? Who is it damning? Oh. I don''t want to know.  Made my top 3.', '2013-07-20 16:01:40.000000', NULL, 1),
(7074591, 1075433, 50641, '<td valign="top">We decided to stage a play amongst the toadstools, under the arching dead oak tree. The golden rooster had agreed to be a prop and struck a pose, stage right. It was early Spring, the grass had just turned from sickly yellow brown to a bright, pastel green and the sky was storybook blue. Windowpanes had been hung all over the set so that the actors wouldn''t be tempted to fly away. Our director was once again pantsless, saying something about the delicious breeze. The exposition imparted a certain gravitas to his instructions. With the morning mist came our deus ex machina - it was the face of Dog, wavering stage left. Company bow. Wow. <br/> <br/> <br/>Made my top 3.</td>', 'We decided to stage a play amongst the toadstools, under the arching dead oak tree. The golden rooster had agreed to be a prop and struck a pose, stage right. It was early Spring, the grass had just turned from sickly yellow brown to a bright, pastel green and the sky was storybook blue. Windowpanes had been hung all over the set so that the actors wouldn''t be tempted to fly away. Our director was once again pantsless, saying something about the delicious breeze. The exposition imparted a certain gravitas to his instructions. With the morning mist came our deus ex machina - it was the face of Dog, wavering stage left. Company bow. Wow.   Made my top 3.', '2013-07-20 16:02:21.000000', NULL, 1),
(7074592, 1075871, 50641, '<td valign="top">I adore this inky straddling of reason and chaos.</td>', 'I adore this inky straddling of reason and chaos.', '2013-07-20 16:03:10.000000', NULL, 1),
(7074593, 1075711, 50641, '<td valign="top">Doctor my eyes. Finally an explanation for this distorted view of life. Worse than a demon on your shoulder is a beetle under your iris, turning your vitreous humor vitriolic. I cannot see the sky. <br/> <br/>Made my top 5.</td>', 'Doctor my eyes. Finally an explanation for this distorted view of life. Worse than a demon on your shoulder is a beetle under your iris, turning your vitreous humor vitriolic. I cannot see the sky.  Made my top 5.', '2013-07-20 16:03:39.000000', NULL, 1),
(7074594, 1075906, 50641, '<td valign="top">We were mesmerized by the gleaming city as we were all sucked, streaming by in vacuum-tube capsule cars on our way from NY to LA. I pretended it was Dubai, but more likely it was just a sunglorified Oklahoma City. Its only true location is in this blur of moment. <br/> <br/>Made my top 5.</td>', 'We were mesmerized by the gleaming city as we were all sucked, streaming by in vacuum-tube capsule cars on our way from NY to LA. I pretended it was Dubai, but more likely it was just a sunglorified Oklahoma City. Its only true location is in this blur of moment.  Made my top 5.', '2013-07-20 16:04:26.000000', NULL, 1),
(7074618, 1075446, 63218, '<td valign="top">This is so special. That is one very tight dress.</td>', 'This is so special. That is one very tight dress.', '2013-07-20 17:45:55.000000', NULL, 1),
(7074620, 1075906, 63218, '<td valign="top">real nice light</td>', 'real nice light', '2013-07-20 17:58:12.000000', NULL, 1),
(7074627, 1075534, 63218, '<td valign="top">Ha! the chair has a lot of personality. The shot seems casuaaccidental fine art.l, momentary--but the effect of it is...I don''t know. I don''t have the words.</td>', 'Ha! the chair has a lot of personality. The shot seems casuaaccidental fine art.l, momentary--but the effect of it is...I don''t know. I don''t have the words.', '2013-07-20 18:32:30.000000', NULL, 1),
(7074628, 1075924, 63218, '<td valign="top">Nice light. It always comes down to the light.</td>', 'Nice light. It always comes down to the light.', '2013-07-20 18:35:11.000000', NULL, 1),
(7074631, 1075915, 63218, '<td valign="top">Woot! a classic!</td>', 'Woot! a classic!', '2013-07-20 18:42:56.000000', NULL, 1),
(7074632, 1075938, 63218, '<td valign="top">such sad eyes</td>', 'such sad eyes', '2013-07-20 18:45:59.000000', NULL, 1),
