(7075930, 1075945, 12611, '<td valign="top">Abstract meets realism, in a world of shadow and light and bluebirds. Its ringing in my ears.<br/> <br/>(A top choice of mine. well done)</td>', 'Abstract meets realism, in a world of shadow and light and bluebirds. Its ringing in my ears. (A top choice of mine. well done)', '2013-07-23 12:55:58.000000', NULL, 1),
(7075932, 1075297, 12611, '<td valign="top">Entomology meets geometry, a match made in electric blue heaven.<br/> <br/>a top pick for me.</td>', 'Entomology meets geometry, a match made in electric blue heaven. a top pick for me.', '2013-07-23 12:58:48.000000', NULL, 1),
(7075934, 1075866, 12611, '<td valign="top">I love the use of light, and the way the tilt of the screen and frailty of the bench leave the viewer ill at ease. The upper right corner is a great addition (the background that appears as if it was made in an era of painting prior to the development of perspective.)</td>', 'I love the use of light, and the way the tilt of the screen and frailty of the bench leave the viewer ill at ease. The upper right corner is a great addition (the background that appears as if it was made in an era of painting prior to the development of perspective.)', '2013-07-23 13:02:21.000000', NULL, 1),
(7075935, 1075580, 12611, '<td valign="top">I am drawn to the area of the hip, the stretchmarks bring a photographic realism to wonderfully composed line and tone.</td>', 'I am drawn to the area of the hip, the stretchmarks bring a photographic realism to wonderfully composed line and tone.', '2013-07-23 13:03:25.000000', NULL, 1),
(7075936, 1075450, 12611, '<td valign="top">A terrific feel,( a triumph in that the shot oozes "classic" and yet the guy has a watch and gym shorts on.)<br/> <br/>Perhaps the victory is in the tones.</td>', 'A terrific feel,( a triumph in that the shot oozes "classic" and yet the guy has a watch and gym shorts on.) Perhaps the victory is in the tones.', '2013-07-23 13:03:29.000000', NULL, 1),
(7075939, 1075433, 12611, '<td valign="top">I am sufficiently won over by the lush tan and teal, areas of detail that open up, all from a perspective of the flip=flop wearing, khaki pants sporting platform walker, as he witness the fight of a lifetime.<br/> <br/>(a personal top pick of mine).</td>', 'I am sufficiently won over by the lush tan and teal, areas of detail that open up, all from a perspective of the flip=flop wearing, khaki pants sporting platform walker, as he witness the fight of a lifetime. (a personal top pick of mine).', '2013-07-23 13:05:36.000000', NULL, 1),
(7075958, 1075900, 12611, '<td valign="top">Excellent work: Simplistic, perfect elements of line and tone; the title provides and avenue, the viewer must walk the path for himself.</td>', 'Excellent work: Simplistic, perfect elements of line and tone; the title provides and avenue, the viewer must walk the path for himself.', '2013-07-23 13:54:08.000000', NULL, 1),
(7075959, 1075948, 12611, '<td valign="top">I can certainly feel the empathy, and the fact that there is no where to rest your eyes to focus. Stuck in the middle and out of place, the unwanted, different child.</td>', 'I can certainly feel the empathy, and the fact that there is no where to rest your eyes to focus. Stuck in the middle and out of place, the unwanted, different child.', '2013-07-23 13:56:41.000000', NULL, 1),
(7075960, 1075859, 12611, '<td valign="top">I particularly like the tree at the end of the street, and the light on the gentleman is perfect- masterful.</td>', 'I particularly like the tree at the end of the street, and the light on the gentleman is perfect- masterful.', '2013-07-23 13:57:51.000000', NULL, 1),
(7075971, 1075890, 12611, '<td valign="top">I love the obscuring, the unknowing, the lack of showing. A still life with secrets.</td>', 'I love the obscuring, the unknowing, the lack of showing. A still life with secrets.', '2013-07-23 14:12:21.000000', NULL, 1),
(7075973, 1075912, 12611, '<td valign="top">The light here is unmistakably good.</td>', 'The light here is unmistakably good.', '2013-07-23 14:17:12.000000', NULL, 1),
(7075974, 1075273, 12611, '<td valign="top">You have taught a lesson. A top pick for me.</td>', 'You have taught a lesson. A top pick for me.', '2013-07-23 14:18:03.000000', NULL, 1),
(7075975, 1075652, 12611, '<td valign="top">Excellent concept, also, a truly brutal, unrelenting, ugly, beautiful- all at the same time.</td>', 'Excellent concept, also, a truly brutal, unrelenting, ugly, beautiful- all at the same time.', '2013-07-23 14:23:08.000000', NULL, 1),
(7075977, 1075271, 12611, '<td valign="top">A salute from the tower that holds the urban princess. A terrific exercise in contrast.</td>', 'A salute from the tower that holds the urban princess. A terrific exercise in contrast.', '2013-07-23 14:28:05.000000', NULL, 1),
(7075978, 1075852, 12611, '<td valign="top">Dark and terrible and dripping with blood and fluids and wood stain. Excellent work and the sacrifice is accepted.</td>', 'Dark and terrible and dripping with blood and fluids and wood stain. Excellent work and the sacrifice is accepted.', '2013-07-23 14:29:25.000000', NULL, 1),
(7075986, 1075867, 12611, '<td valign="top">The colors and the tall aspect ratio made me back a bit off of this photo, made it difficult to assess. However, I returned, and I am aware of details, the McDonalds sign, the Chinese script, the wires upon wires. If this was the view out of a window in Hong Kong, for instance, I would expect nothing less.</td>', 'The colors and the tall aspect ratio made me back a bit off of this photo, made it difficult to assess. However, I returned, and I am aware of details, the McDonalds sign, the Chinese script, the wires upon wires. If this was the view out of a window in Hong Kong, for instance, I would expect nothing less.', '2013-07-23 14:38:07.000000', NULL, 1),
(7076045, 1075608, 144271, '<td valign="top">Beautiful motion shot</td>', 'Beautiful motion shot', '2013-07-23 16:48:15.000000', NULL, 1),
