(7076367, 1075879, 30214, '<td valign="top">strong image Mark.</td>', 'strong image Mark.', '2013-07-24 02:56:13.000000', NULL, 0),
(7076369, 1075822, 113591, '<td valign="top">This one really grabbed my attention. It is real-life, every-day, and whimsical.<br/>A circle of learning, doing, being.<br/> <br/>And the title works so well too.<br/> <br/>Thanks.<br/></td>', 'This one really grabbed my attention. It is real-life, every-day, and whimsical.A circle of learning, doing, being. And the title works so well too. Thanks.', '2013-07-24 03:05:40.000000', NULL, 0),
(7076371, 1075506, 113591, '<td valign="top">This was in and out of my 3 choices for the Alt-Jury. Must confess, you nailed the title, but even without it, the image crept into my heart the first time I saw it. The viewpoint, the waving hands, the smile, it''s all so personal. An image to treasure. Thank you for sharing it.</td>', 'This was in and out of my 3 choices for the Alt-Jury. Must confess, you nailed the title, but even without it, the image crept into my heart the first time I saw it. The viewpoint, the waving hands, the smile, it''s all so personal. An image to treasure. Thank you for sharing it.', '2013-07-24 03:12:46.000000', NULL, 0),
(7076373, 1075949, 113591, '<td valign="top">Made me sad. Fading against one''s will. Powerless, even in the new technology-driven world. Thanks.</td>', 'Made me sad. Fading against one''s will. Powerless, even in the new technology-driven world. Thanks.', '2013-07-24 03:18:01.000000', NULL, 0),
(7076374, 1075938, 28427, '<td valign="top">I wished the notes would tell us a bit more on this.<br/>I found this so odd, beautiful, scary, artistic...all at the same time.</td>', 'I wished the notes would tell us a bit more on this.I found this so odd, beautiful, scary, artistic...all at the same time.', '2013-07-24 03:18:33.000000', NULL, 0),
