INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7076433, 1075949, 76335, '<td valign="top">This is intense. As my attentions were elsewhere during this challenge, I missed the opportunity to revisit it, get lost in it.</td>', 'This is intense. As my attentions were elsewhere during this challenge, I missed the opportunity to revisit it, get lost in it.', '2013-07-24 08:23:37.000000', NULL, 0),
(7076435, 1075652, 76335, '<td valign="top">The silent struggle between man and nature continues. Perfectly framed -- tigther or wider would have given victory to one or the other.</td>', 'The silent struggle between man and nature continues. Perfectly framed -- tigther or wider would have given victory to one or the other.', '2013-07-24 08:28:19.000000', NULL, 0),
