(7076437, 1075785, 109227, '<td valign="top">Oh my, maybe I don''t know art very well; this should be in the top three.  Beautiful.</td>', 'Oh my, maybe I don''t know art very well; this should be in the top three.  Beautiful.', '2013-07-24 08:35:29.000000', NULL, 0),
(7076438, 1075869, 76335, '<td valign="top">Another one of those that other distractions [clears throat] kept me from revisiting and appreciating. A backdrop for a daydream. Calming. Beautiful.</td>', 'Another one of those that other distractions [clears throat] kept me from revisiting and appreciating. A backdrop for a daydream. Calming. Beautiful.', '2013-07-24 08:38:39.000000', NULL, 0),
