(7076441, 1075534, 76335, '<td valign="top">A chair? Or a futuristic robotic spider-egg about to pounce? Scary as hell. A nine from me.</td>', 'A chair? Or a futuristic robotic spider-egg about to pounce? Scary as hell. A nine from me.', '2013-07-24 08:42:12.000000', NULL, 0),
(7076442, 1075890, 76335, '<td valign="top">Beautifully understated still life.</td>', 'Beautifully understated still life.', '2013-07-24 08:44:57.000000', NULL, 0),
(7076443, 1075949, 11769, '<td valign="top">If I keep talking about it I will remember, I see that streak of light when I close my eyes and go to sleep.</td>', 'If I keep talking about it I will remember, I see that streak of light when I close my eyes and go to sleep.', '2013-07-24 08:46:01.000000', NULL, 0),
(7076445, 1075879, 109227, '<td valign="top">Congrats on TT; thought this would be higher up.  Very moving image.</td>', 'Congrats on TT; thought this would be higher up.  Very moving image.', '2013-07-24 08:55:07.000000', NULL, 0),
(7076447, 1075652, 100831, '<td valign="top">Gripping.</td>', 'Gripping.', '2013-07-24 08:58:58.000000', NULL, 0),
(7076450, 1075580, 109227, '<td valign="top">Beautifully done Nadine; love your notes, as I too have been in the same place and pushed myself to do this for the nude challenge.  Still makes me nervous to know it is here for the world to see, but still a triumph for me as a woman.  Glad that you followed your instinct.</td>', 'Beautifully done Nadine; love your notes, as I too have been in the same place and pushed myself to do this for the nude challenge.  Still makes me nervous to know it is here for the world to see, but still a triumph for me as a woman.  Glad that you followed your instinct.', '2013-07-24 09:01:19.000000', NULL, 0),
(7076454, 1075953, 100831, '<td valign="top">Amazing ..... You out did yourself for sure. Funny but I wonder if a title that didn''t make reference to Spider-Man would have changed our impressions.</td>', 'Amazing ..... You out did yourself for sure. Funny but I wonder if a title that didn''t make reference to Spider-Man would have changed our impressions.', '2013-07-24 09:08:34.000000', NULL, 0),
